const _r = $input.first().json;
const p = (_r && _r.data) ? _r.data : _r;
const state = Array.isArray(p) ? p[0] : p;
const ops = (state.opportunities || []).filter(o => !o.legal_block);

// Deduplicate to one entry per world: keep the highest-scoring engine/format variant.
// Without this the top ten is ten near-identical rows for the same setting.
const best = {};
for (const o of ops) if (!best[o.world] || o.score_total > best[o.world].score_total) best[o.world] = o;
const ranked = Object.values(best).sort((a, b) => b.score_total - a.score_total);
// DEF-03 confidence gate. under_service and evidence_breadth are anti-correlated by
// construction: a world seen once looks under-supplied when in fact it is merely
// under-observed. Worlds carrying fewer than MIN_EVIDENCE distinct evidence records
// are scored but held out of the ranked digest as thin-evidence candidates.
const MIN_EVIDENCE = 2;
const confident = ranked.filter(o => o.world_evidence_count >= MIN_EVIDENCE);
const thin = ranked.filter(o => o.world_evidence_count < MIN_EVIDENCE);
const top = confident.slice(0, 10);

const pretty = (s) => String(s).replace(/_/g, ' ');
const pct = (x) => Math.round(x * 100) + '%';

const theses = top.map((o, i) => {
  const v = o.score_vector;
  const drivers = Object.entries(o.score_contribution).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([k, val]) => pretty(k) + ' (' + val + ')');
  const weak = Object.entries(o.score_vector).sort((a, b) => a[1] - b[1]).slice(0, 2).map(([k, val]) => pretty(k) + ' ' + pct(val));

  const routeRead = v.route_accessibility >= 0.65
    ? 'Reachable: the strongest route for this format is a public-service buyer, and those are the only buyers in the corpus with evidenced open-access submission schemes.'
    : (v.route_accessibility >= 0.5
      ? 'Partially reachable: the dominant buyers for this format run no evidenced open submission route, so access depends on a producer relationship.'
      : 'Hard to reach: the dominant buyers for this format are evidenced as closed to unsolicited material.');

  const feasRead = v.production_feasibility >= 0.9
    ? 'Very low production cost relative to high-end TV, which matters because the corpus shows a deficit-financing crisis rather than a commissioning-appetite crisis.'
    : (v.production_feasibility >= 0.7
      ? 'Contained format, consistent with corpus evidence that buyers are prioritising cheaper, faster-to-make material.'
      : 'Higher production load; this competes directly for the scarcest financing in the corpus.');

  const serviceRead = v.under_service >= 0.85
    ? 'This setting is materially under-supplied relative to the genre demand attached to it.'
    : (v.under_service >= 0.6 ? 'This setting is modestly under-supplied relative to its genre demand.' : 'This setting is already well served.');

  return {
    rank: i + 1,
    intersection_id: o.intersection_id,
    world: o.world,
    engine: o.engine,
    format: o.format,
    genres: o.genres,
    score_total: o.score_total,
    governance_band: o.governance_band,
    legal_review_required: o.legal_review_required,
    world_supply_weight: o.world_supply_weight,
    world_evidence_count: o.world_evidence_count,
    evidence_support: o.evidence_support,
    top_drivers: drivers,
    weakest_dimensions: weak,
    thesis: 'A ' + pretty(o.format) + ' set in ' + pretty(o.world) + ', driven by ' + pretty(o.engine) + '. ' + serviceRead + ' ' + routeRead + ' ' + feasRead
  };
});

// ---- Format-level finding, independent of any single intersection ----
const fmt = {};
for (const o of ops) { fmt[o.format] = fmt[o.format] || []; fmt[o.format].push(o); }
const formatFindings = Object.entries(fmt).map(([f, arr]) => ({
  format: f,
  n: arr.length,
  mean_score: Number((arr.reduce((s, o) => s + o.score_total, 0) / arr.length).toFixed(2)),
  mean_route: Number((arr.reduce((s, o) => s + o.score_vector.route_accessibility, 0) / arr.length).toFixed(3)),
  mean_feasibility: Number((arr.reduce((s, o) => s + o.score_vector.production_feasibility, 0) / arr.length).toFixed(3)),
  mean_buyer_demand: Number((arr.reduce((s, o) => s + o.score_vector.buyer_demand, 0) / arr.length).toFixed(3))
})).sort((a, b) => b.mean_score - a.mean_score);

// ---- Markdown digest ----
const L = [];
L.push('# FILM/TV DEMAND MINE v0.1 — CHAIRMAN DIGEST');
L.push('');
L.push('Generated: ' + new Date().toISOString());
L.push('Scoring model: ' + state.scoring_model_version);
L.push('Candidates scored: ' + state.input_count + ' | Legally blocked: ' + state.blocked_count + ' | Distinct worlds: ' + ranked.length + ' | Passing evidence gate (>=2 records): ' + confident.length + ' | Held out as thin: ' + thin.length);
L.push('');
L.push('## Governance bands');
L.push('');
for (const [b, n] of Object.entries(state.band_counts || {})) L.push('- ' + pretty(b) + ': ' + n);
L.push('');
L.push('## Format-level finding');
L.push('');
L.push('| Format | Mean score | Buyer demand | Route access | Feasibility |');
L.push('|---|---|---|---|---|');
for (const f of formatFindings) L.push('| ' + pretty(f.format) + ' | ' + f.mean_score + ' | ' + pct(f.mean_buyer_demand) + ' | ' + pct(f.mean_route) + ' | ' + pct(f.mean_feasibility) + ' |');
L.push('');
L.push('## Top 10 opportunity theses');
L.push('');
for (const t of theses) {
  L.push('### ' + t.rank + '. ' + pretty(t.world) + ' x ' + pretty(t.engine) + ' — score ' + t.score_total);
  L.push('');
  L.push('- **Format:** ' + pretty(t.format));
  L.push('- **Genres:** ' + t.genres.map(pretty).join(', '));
  L.push('- **Band:** ' + pretty(t.governance_band) + (t.legal_review_required ? ' — LEGAL REVIEW REQUIRED' : ''));
  L.push('- **Top drivers:** ' + t.top_drivers.join('; '));
  L.push('- **Weakest:** ' + t.weakest_dimensions.join('; '));
  L.push('- **Evidence:** ' + t.evidence_support.join(', '));
  L.push('');
  L.push(t.thesis);
  L.push('');
}

return [{ json: {
  stage: 'WF-15',
  generated_at: new Date().toISOString(),
  scoring_model_version: state.scoring_model_version,
  candidates_screened: state.input_count,
  blocked_count: state.blocked_count,
  distinct_worlds: ranked.length,
  confidence_gate_min_evidence: MIN_EVIDENCE,
  worlds_passing_gate: confident.length,
  worlds_held_thin: thin.length,
  thin_worlds: thin.slice(0,15).map(o=>({world:o.world,score:o.score_total,evidence_count:o.world_evidence_count})),
  band_counts: state.band_counts,
  format_findings: formatFindings,
  top_10: theses,
  markdown: L.join('\n')
} }];
